$(function() {
    $('.sales-datepicker').datepicker({
        dateFormat: 'dd/mm/yy',
        minDate:'-2',
        maxDate:'0'
    });

    $('.voucher-datepicker').datepicker({
        dateFormat: 'dd/mm/yy',
        minDate:'-2',
        maxDate:'0'
    });


    $('.datepicker').datepicker({
        dateFormat: 'dd/mm/yy',
        minDate:'0'
    });

    $( ".datepicker, .voucher-datepicker, .sales-datepicker" ).inputmask({ alias: "datetime", inputFormat: "dd/mm/yyyy", "placeholder": "DD/MM/YYYY", "mode": "numeric" });
});

$( function() {
    var dateFormat = "dd/mm/yy",
        from = $( "#reservationfrom" ).datepicker({
            defaultDate: "+1w",
            changeMonth: true,
            changeYear: true,
            dateFormat:dateFormat,
            minDate:'-1d'
        })
            .on( "change", function() {
                to.datepicker( "option", "minDate", getDate( this ) );
            }),
        to = $( "#reservationto" ).datepicker({
            defaultDate: "+1w",
            changeMonth: true,
            changeYear: true,
            dateFormat:dateFormat,
            minDate:'-1d'
        });
// .on( "change", function() {
//         from.datepicker( "option", "maxDate", getDate( this ) );
//     })
    function getDate( element ) {
        var date;
        try {
            date = $.datepicker.parseDate( dateFormat, element.value );
        } catch( error ) {
            date = null;
        }

        return date;
    }

    $( "#reservationfrom, #reservationto" ).inputmask({ alias: "datetime", inputFormat: "dd/mm/yyyy", "placeholder": "DD/MM/YYYY", "mode": "numeric" });
});


