$( function() {
    $('#reserve-datepicker').datepicker({
        dateFormat: 'dd/mm/yy',
        maxDate:'0'
    }).on( "change", function() {
        var date = $(this).val();
        var obj = $(this);
        var form = obj.closest('form');
        formReset(form);
        form.find('.readonlywithdate').addClass('readonly');
        var url = obj.data('link');
        obj.val(date);
        $.ajax({
            url : url,
            type: "GET",
            data : {date:date},
            dataType:'JSON',
            success: function(data)
            {
                if(data.status == 1 && data.debit > 0){
                    form.find('#plbalance').val(data.debit);
                    form.find('#inamount').attr('max',data.debit);
                    form.find('.readonlywithdate').removeClass('readonly');
                }
            },
            error: function (data)
            {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });


    $(document).on("change keyup", '#reserve_voucher #inpercent', function (e) {
        $('#inamount').val(applyPercent($('#plbalance').val(), $('#inpercent').val()));
    });

    $(document).on("change keyup", '#reserve_voucher #inamount', function (e) {
        $('#inpercent').val(getPercent($('#plbalance').val(), $('#inamount').val()));
    });


});

//////////////////////
$.extend($.datepicker, {
    _doKeyDown: function(event) {
        var onSelect, dateStr, sel,
            inst = $.datepicker._getInst(event.target),
            handled = true,
            isRTL = inst.dpDiv.is(".ui-datepicker-rtl");
        inst._keyEvent = true;
        if ($.datepicker._datepickerShowing) {
            switch (event.keyCode) {
                case 9: $.datepicker._hideDatepicker();
                    handled = false;
                    break; // hide on tab out
                case 13: sel = $("td." + $.datepicker._dayOverClass + ":not(." +
                    $.datepicker._currentClass + ")", inst.dpDiv);
                    if (sel[0]) {
                        $.datepicker._selectDay(event.target, inst.selectedMonth, inst.selectedYear, sel[0]);
                    }

                    onSelect = $.datepicker._get(inst, "onSelect");
                    if (onSelect) {
                        dateStr = $.datepicker._formatDate(inst);

                        // trigger custom callback
                        onSelect.apply((inst.input ? inst.input[0] : null), [dateStr, inst]);
                    } else {
                        $.datepicker._hideDatepicker();
                    }

                    return false; // don't submit the form
                case 27: $.datepicker._hideDatepicker();
                    break; // hide on escape
                case 33: $.datepicker._adjustDate(event.target, (event.ctrlKey ?
                    -$.datepicker._get(inst, "stepBigMonths") :
                    -$.datepicker._get(inst, "stepMonths")), "M");
                    break; // previous month/year on page up/+ ctrl
                case 34: $.datepicker._adjustDate(event.target, (event.ctrlKey ?
                    +$.datepicker._get(inst, "stepBigMonths") :
                    +$.datepicker._get(inst, "stepMonths")), "M");
                    break; // next month/year on page down/+ ctrl
                case 35: if (event.ctrlKey || event.metaKey) {
                    $.datepicker._clearDate(event.target);
                }
                    handled = event.ctrlKey || event.metaKey;
                    break; // clear on ctrl or command +end
                case 36: if (event.ctrlKey || event.metaKey) {
                    $.datepicker._gotoToday(event.target);
                }
                    handled = event.ctrlKey || event.metaKey;
                    break; // current on ctrl or command +home
                case 37:    $.datepicker._adjustDate(event.target, (isRTL ? +1 : -1), "D");

                    handled = event.ctrlKey || event.metaKey;
                    // -1 day on ctrl or command +left
                    if (event.originalEvent.altKey) {
                        $.datepicker._adjustDate(event.target, (event.ctrlKey ?
                            -$.datepicker._get(inst, "stepBigMonths") :
                            -$.datepicker._get(inst, "stepMonths")), "M");
                    }
                    // next month/year on alt +left on Mac
                    break;
                case 38:    $.datepicker._adjustDate(event.target, -7, "D");

                    handled = event.ctrlKey || event.metaKey;
                    break; // -1 week on ctrl or command +up
                case 39:    $.datepicker._adjustDate(event.target, (isRTL ? -1 : +1), "D");

                    handled = event.ctrlKey || event.metaKey;
                    // +1 day on ctrl or command +right
                    if (event.originalEvent.altKey) {
                        $.datepicker._adjustDate(event.target, (event.ctrlKey ?
                            +$.datepicker._get(inst, "stepBigMonths") :
                            +$.datepicker._get(inst, "stepMonths")), "M");
                    }
                    // next month/year on alt +right
                    break;
                case 40:    $.datepicker._adjustDate(event.target, +7, "D");

                    handled = event.ctrlKey || event.metaKey;
                    break; // +1 week on ctrl or command +down
                default: handled = false;
            }
        } else if (event.keyCode === 36 && event.ctrlKey) { // display the date picker on ctrl+home
            $.datepicker._showDatepicker(this);
        } else {
            handled = false;
        }

        if (handled) {
            event.preventDefault();
            event.stopPropagation();
        }
    }
});
